INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '17c401c0-467f-4040-8d67-d01e06c1d28d',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '33. óra: Ismerkedés a törtekkel',
        'Közönséges tört, számláló, nevező, törtvonal értelmezése.',
        'Matematika',
        '5. osztály',
        'Törtek',
        '[{"id": "f190b005-8622-42e6-8bea-b67d9bc9755a", "text": "Melyik kifejezés mutatja meg, hogy az egész hány egyenlő részre van osztva?", "type": "multiple-choice", "options": [{"id": "1c1213d6-1cba-4cb4-b0b5-8c790a9ffd76", "text": "Számláló", "isCorrect": false}, {"id": "f2905404-e8bc-4f39-a3a3-484d1eab56d9", "text": "Nevező", "isCorrect": true}, {"id": "9ba428cf-e631-41e0-bd5f-71e0265d4597", "text": "Törtvonal", "isCorrect": false}, {"id": "82d97518-f653-429b-b537-80c4436da292", "text": "Összeg", "isCorrect": false}], "timeLimit": 15}, {"id": "5db986d4-32ea-4786-b4d1-8e9b87b379b6", "text": "Melyik kifejezés mutatja meg, hogy hány részt vettünk az egyenlő részekre osztott egészből?", "type": "multiple-choice", "options": [{"id": "2af2d552-81ad-438e-8154-809b9deee218", "text": "Nevező", "isCorrect": false}, {"id": "56625e33-7acc-44de-81d8-1f086dbde3c5", "text": "Számláló", "isCorrect": true}, {"id": "8e85a305-b481-4ae8-a621-6ad8c9a28c08", "text": "Törtvonal", "isCorrect": false}, {"id": "db8f8cf1-24ce-4b9f-9247-1daa18e0e7ee", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "baee88fd-81d9-4132-9fc3-180fa2e36a76", "text": "A 3/4 törtben a 3 a nevező és a 4 a számláló.", "type": "true-false", "options": [{"id": "4cf49873-8373-411b-a177-d03507bfa78d", "text": "Igaz", "isCorrect": false}, {"id": "d6c52671-d28d-49f5-ab01-debf6573f890", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "83b18e3f-f8c3-4769-9eb1-1ab25f48286c", "text": "Ha egy tortát 8 egyenlő szeletre vágunk és megeszünk 3 szeletet, a torta hányad részét ettük meg? (Írd le tört alakban, pl: 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3/8"}, {"id": "bbe12653-2067-4941-84d9-390b09e18416", "text": "Melyik tört felel meg a ''kétötöd'' kifejezésnek?", "type": "multiple-choice", "options": [{"id": "e7385a01-611e-4574-a58c-25bb78227fcf", "text": "5/2", "isCorrect": false}, {"id": "f300d112-f84f-4239-ad30-e7248d9ac420", "text": "2/5", "isCorrect": true}, {"id": "34a85a4d-ec69-4a55-86ef-dbf6b0b37790", "text": "2/3", "isCorrect": false}, {"id": "9e937341-564b-42ac-9e4d-0d44a9e5abc1", "text": "3/5", "isCorrect": false}], "timeLimit": 15}, {"id": "cca21764-c393-4a36-a4ac-6d43ce6b8951", "text": "A törtvonal az osztás műveletét helyettesíti.", "type": "true-false", "options": [{"id": "b2a16e33-3c65-4c17-8e88-4fbe43f2a396", "text": "Igaz", "isCorrect": true}, {"id": "8c981446-552f-435a-9ada-81f28e03b7fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "530cf502-c9de-4568-bc63-35da1ff380e5", "text": "Hány harmad részből áll egy egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "7019155d-a079-4e95-a1d5-1d3501b93331", "text": "Mit jelent az 1/2 tört?", "type": "multiple-choice", "options": [{"id": "7738e725-2258-4089-b06e-bf44cfd9daab", "text": "Egy harmadot", "isCorrect": false}, {"id": "88c08baf-c163-444f-901a-f8341ef12732", "text": "Félt (egy kettedet)", "isCorrect": true}, {"id": "18fa58be-20a9-4aab-97a3-1219a1d8f84e", "text": "Két egészet", "isCorrect": false}, {"id": "bbafe07a-3aa1-4323-8228-f142bcd2bd78", "text": "Negyedszet", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '0b2815a2-7d55-43f7-af68-8d87ec4f8564',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '34. óra: Törtrészek ábrázolása, a törtszámok használata',
        'Törtrészek ábrázolásának gyakorlása, alakzatok színezése és törtértékek.',
        'Matematika',
        '5. osztály',
        'Törtek',
        '[{"id": "d0771eaf-06ab-449c-9957-25d61066f326", "text": "Ha egy kör 6 egyenlő cikkéből 4 cikk be van színezve, a kör hányad része színes?", "type": "multiple-choice", "options": [{"id": "af2a0b7a-f80b-49f5-9882-461a1a2105ff", "text": "2/6", "isCorrect": false}, {"id": "08ecc77c-0103-486b-b474-8e4bb57eadd0", "text": "4/6", "isCorrect": true}, {"id": "6a20f3c7-4f76-45f9-843d-3f575f9255e9", "text": "6/4", "isCorrect": false}, {"id": "20be6e27-a728-464c-a581-d45955d78a95", "text": "1/4", "isCorrect": false}], "timeLimit": 15}, {"id": "ea07a962-39f6-4b74-92a6-65b51ed02a05", "text": "Ha egy szakasz 10 cm hosszú, mennyi a szakasz 3/5 része? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ae4c61b4-67e2-47ba-9ea3-9009326f51c7", "text": "Az 5/5 tört értéke pontosan 1 egész.", "type": "true-false", "options": [{"id": "64abbb50-8b29-4942-882e-bd8ebd40d9a2", "text": "Igaz", "isCorrect": true}, {"id": "5e88c77c-c7ee-4970-b856-1eb5eacb2c06", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6bdc41d7-7768-4e01-b152-86ed540a0291", "text": "Mennyi 24-nek az 1/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4f5191ec-9f27-49c1-ad4a-d949695a7926", "text": "Mennyi 20-nak a 3/4 része?", "type": "multiple-choice", "options": [{"id": "cc7bd7da-3f52-4ab3-8f8f-9d80348350bb", "text": "5", "isCorrect": false}, {"id": "d57fcfd0-3087-4c9d-becd-12d484302b7e", "text": "10", "isCorrect": false}, {"id": "9333bb5b-4f28-4d26-b882-d11c982d1700", "text": "15", "isCorrect": true}, {"id": "566e5003-d65d-4382-b0a4-938f4cb740c0", "text": "12", "isCorrect": false}], "timeLimit": 15}, {"id": "c8350a52-1925-4e74-8bc4-856ecbb8b9a4", "text": "Ha a számláló kisebb a nevezőnél, a tört értéke kisebb 1-nél.", "type": "true-false", "options": [{"id": "d077fc11-6f3a-4e92-9508-52381215e4cf", "text": "Igaz", "isCorrect": true}, {"id": "5b94d1bd-80ba-406d-8171-f3ed4b632a4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c9931d5-54fe-4d79-bdb2-ae937a04aa29", "text": "Ha egy téglalap 8 egyenlő kockából áll és 3 kocka piros, hányad része NEM piros?", "type": "multiple-choice", "options": [{"id": "e822ccae-202f-48fa-8765-56ad6d5c89cb", "text": "3/8", "isCorrect": false}, {"id": "18b9253f-383d-46f5-a475-da8d9fd71739", "text": "5/8", "isCorrect": true}, {"id": "cc562206-9160-4d75-9b85-9b8ffbbbf2a9", "text": "8/3", "isCorrect": false}, {"id": "3afb7f38-0a57-4e82-9efc-b596676e7893", "text": "1/2", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        'fbce398d-09b5-4ff0-94e4-6bb714d36633',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '35. óra: Törtek bővítése, egyszerűsítése, összehasonlítása',
        'Törtek bővítésének és egyszerűsítésének szabályai, egyenlő értékű törtek.',
        'Matematika',
        '5. osztály',
        'Törtek',
        '[{"id": "eb914d1b-399c-4dc5-92c0-7d9036cea348", "text": "Mit jelent a tört bővítése?", "type": "multiple-choice", "options": [{"id": "87f3b56b-29fd-41b8-895d-3cd5f785c0a9", "text": "A számláló és nevező hozzáadását", "isCorrect": false}, {"id": "03d65ccf-55d1-4a2f-a8de-332827c52297", "text": "A számláló és nevező megszorzását ugyanazzal a nem-nulla számmal", "isCorrect": true}, {"id": "0c70cfdc-e8a0-480e-8b50-f45d8069bfb1", "text": "A nevező növelését", "isCorrect": false}, {"id": "9ef4d456-399e-4989-8955-c9296dac5248", "text": "A számláló kettőzését", "isCorrect": false}], "timeLimit": 15}, {"id": "77700676-3004-443c-854f-c30acf323d7e", "text": "Mit jelent a tört egyszerűsítése?", "type": "multiple-choice", "options": [{"id": "0c2d38d2-0546-4857-9e95-39de7f7b5931", "text": "A számláló és nevező elosztását ugyanazzal a nem-nulla közös osztóval", "isCorrect": true}, {"id": "6b001f6d-288e-4eeb-a458-fb8453ac1214", "text": "A számláló kivonását a nevezőből", "isCorrect": false}, {"id": "81a5dae5-8b26-427c-89b1-5ad5a3209b3c", "text": "A tört törlését", "isCorrect": false}, {"id": "989ef66d-e8c3-412e-a2e0-85cc27f78770", "text": "A nevező felezését", "isCorrect": false}], "timeLimit": 15}, {"id": "124487c6-772b-4dc8-9ac9-8b20dda6e222", "text": "Bővítéskor vagy egyszerűsítéskor a tört értéke nem változik.", "type": "true-false", "options": [{"id": "176644c7-9548-4b2f-aceb-b7c679ef4173", "text": "Igaz", "isCorrect": true}, {"id": "3cebef4b-4f5d-46ee-a8c0-39f6de7c0229", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f87ce24f-4900-4983-aba3-c9864de51b63", "text": "Bővítsd az 1/2 törtet 3-mal! Milyen törtet kapsz? (pl: 3/6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3/6"}, {"id": "ed5d5a2e-bbdd-4e01-9db6-7bb2351f272e", "text": "Egyszerűsítsd a 4/8 törtet a legegyszerűbb alakra!", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1/2"}, {"id": "2c4a900c-069e-4bb0-9eaf-b6f3c37dbf92", "text": "Melyik tört nagyobb: a 3/5 vagy a 4/5?", "type": "multiple-choice", "options": [{"id": "6ad1dd83-7e27-4441-8abc-3f606a3201b4", "text": "3/5", "isCorrect": false}, {"id": "8955639c-f392-4b26-9fb9-d4834b59b1d4", "text": "4/5", "isCorrect": true}, {"id": "cf551669-cbfa-4df4-a85b-cd348f033a2f", "text": "Egyenlőek", "isCorrect": false}, {"id": "3a769a1e-62df-4f4a-8eb7-e9532d02c6db", "text": "Nem hasonlíthatóak össze", "isCorrect": false}], "timeLimit": 15}, {"id": "2b72550c-1194-402a-9410-adc7cc443441", "text": "Két azonos számlálójú tört közül az a nagyobb, amelyiknek a nevezője kisebb.", "type": "true-false", "options": [{"id": "4dd81156-eb8e-49a9-908c-5cbe08491154", "text": "Igaz", "isCorrect": true}, {"id": "70547ef1-6d07-4ed7-8b49-f32e54057812", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '7c5e80bc-f7fd-49eb-a4fc-4886ca286e35',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '36. óra: Gyakorló óra: törtek bővítése, egyszerűsítése, összehasonlítása',
        'Érdekes feladatok a törtek bővítésére, egyszerűsítésére és összehasonlítására.',
        'Matematika',
        '5. osztály',
        'Törtek',
        '[{"id": "2384022c-4d61-4201-9adf-9aeee1b88b54", "text": "Melyik tört egyenlő az 2/3-dal?", "type": "multiple-choice", "options": [{"id": "d616c3dc-fba4-457c-8d3f-d292d01f1982", "text": "4/6", "isCorrect": true}, {"id": "b1f8f595-7cb1-4670-a0ec-1744b2d668a4", "text": "3/4", "isCorrect": false}, {"id": "3719a703-f903-4f70-b184-fba6a86f1c9e", "text": "5/6", "isCorrect": false}, {"id": "f81a1b50-3120-4f82-8ccb-89fcd89df1cf", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "6d2c4329-d2aa-455f-b816-d2775393d5df", "text": "Egyszerűsítsd a 10/15 törtet a legegyszerűbb alakra!", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2/3"}, {"id": "aa8be14e-0cfc-4dbd-992f-2ac7c454b176", "text": "Az 5/10 és a 6/12 törtek értéke egyenlő.", "type": "true-false", "options": [{"id": "4dff5877-843c-433c-8724-99958b0324c4", "text": "Igaz", "isCorrect": true}, {"id": "7eedf363-8b33-4168-a7dd-e10125a47ea9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c51ddc6-4b5a-412b-a937-4fbeebe3b3e7", "text": "Melyik relációs jel illik a 3/4 ... 5/8 közé? (Hozd közös nevezőre: 6/8 ... 5/8)", "type": "multiple-choice", "options": [{"id": "4c99e74c-b834-40f7-b1bb-9fac87072020", "text": ">", "isCorrect": true}, {"id": "a9dd804a-8ef3-4ee2-8165-2baddac4994a", "text": "<", "isCorrect": false}, {"id": "d9f56626-887c-41af-a33a-218b3c3e837d", "text": "=", "isCorrect": false}, {"id": "90ec160f-df3c-46f2-a2ee-75b860d94778", "text": "<=", "isCorrect": false}], "timeLimit": 15}, {"id": "a9c31def-85b5-4c5a-b6ef-8bbd43f52d07", "text": "Bővítsd a 3/7 törtet 4-gyel!", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12/28"}, {"id": "93a3a1bd-880f-479d-93bf-8c9518d19a3f", "text": "A 7/8 nagyobb, mint a 7/10.", "type": "true-false", "options": [{"id": "0a64cc33-0dae-41b5-a079-60205cc25114", "text": "Igaz", "isCorrect": true}, {"id": "0541f66d-555a-497a-a0e2-c4c570272de5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "096582f0-cea5-4c89-834e-4e6da6911d4e", "text": "Egyszerűsítsd a 12/16 törtet!", "type": "multiple-choice", "options": [{"id": "5532cbb4-709f-4f7e-bbc0-ed8f9ff48ad9", "text": "1/2", "isCorrect": false}, {"id": "2e5fea04-8d58-45e0-bd01-adf7610a90ca", "text": "3/4", "isCorrect": true}, {"id": "bf4fa74d-52cc-4985-a1fd-f9ea796ec6a3", "text": "6/8", "isCorrect": false}, {"id": "1304adcc-00d6-4b27-aeca-d6ed2fceef13", "text": "2/3", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '082b7dc1-1d93-492b-8e90-376297ab01ce',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '37. óra: Törtek ábrázolása számegyenesen, vegyes törtek',
        'Törtek elhelyezése a számegyenesen, vegyes tört fogalma és átalakítása.',
        'Matematika',
        '5. osztály',
        'Törtek',
        '[{"id": "6c540793-b584-4444-aade-e98714145bb9", "text": "Mi a vegyes tört?", "type": "multiple-choice", "options": [{"id": "d075f46e-bd91-4eff-90d3-c5c3b2ac975d", "text": "Egész számból és valódi törtből álló alak", "isCorrect": true}, {"id": "ab01a613-6a51-453d-8d5b-7df0096c1922", "text": "Két tört szorzata", "isCorrect": false}, {"id": "0052ffec-f78f-4eb9-89b9-ce41fe4dfd29", "text": "Tizedes tört és közönséges tört összege", "isCorrect": false}, {"id": "cbba6d8c-d7c6-493f-97ab-1383e2b39828", "text": "Negatív tört", "isCorrect": false}], "timeLimit": 15}, {"id": "fc71fe3f-9f39-4081-874c-90e576c5da67", "text": "Írd át az 7/3 ál-törtet vegyes tört alakba! (pl: 2 egész 1/3)", "type": "multiple-choice", "options": [{"id": "3179c5d5-cc09-42c8-989a-b1d830e00859", "text": "2 egész 1/3", "isCorrect": true}, {"id": "178d5765-e32c-4e9f-be10-fdf0ebdb0fc3", "text": "1 egész 4/3", "isCorrect": false}, {"id": "60bfdb61-583f-4873-9031-27720e4c69b8", "text": "3 egész 1/3", "isCorrect": false}, {"id": "e7e52eea-fbdd-4307-a4ee-2635155f8a94", "text": "2 egész 2/3", "isCorrect": false}], "timeLimit": 15}, {"id": "eee19ff5-0e6c-463e-b48b-daf0ceb81a4f", "text": "Alakítsd át a 3 egész 1/2 vegyes törtet közönséges tört alakba! ((3*2+1)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7/2"}, {"id": "799092e2-40f0-4504-88f4-be726329423f", "text": "A számegyenesen az 1 és a 2 egész szám között helyezkedik el a 3/2 (vagyis 1 egész 1/2).", "type": "true-false", "options": [{"id": "a023a18f-6392-4389-b806-b217da0fa6aa", "text": "Igaz", "isCorrect": true}, {"id": "ae218d97-88bf-4ae0-a698-116f9dff5e67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5a4bfdad-3105-4c5e-878a-ad9fcdee1336", "text": "Mennyi a 9/4 tört vegyes tört alakban?", "type": "multiple-choice", "options": [{"id": "05d5c093-fe9a-4c69-b770-73eeed13fe9f", "text": "1 egész 5/4", "isCorrect": false}, {"id": "a2cc529f-0edd-45f4-95ca-198c85fd3b15", "text": "2 egész 1/4", "isCorrect": true}, {"id": "75bd4893-92c0-4373-8621-96ca017303c9", "text": "4 egész 1/2", "isCorrect": false}, {"id": "0e195899-8f4d-48cd-9113-b6bed3df085f", "text": "2 egész 3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "1b5613f5-02ed-4c50-bc4a-297235a5e276", "text": "A 4/4 tört vegyes törtként írandó fel.", "type": "true-false", "options": [{"id": "bf34fa31-6562-4fdd-b089-a0673448cc72", "text": "Igaz", "isCorrect": false}, {"id": "41103708-df6e-456b-802f-a812c83edbe4", "text": "Hamis (ez 1 egész)", "isCorrect": true}], "timeLimit": 15}, {"id": "cf2ced0a-f264-404f-a2e3-0db1d55f90df", "text": "Hány negyedből áll a 2 egész 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );